from pathlib import Path

PAGE = Path("pages/6_Cover_Planner.py")

if not PAGE.exists():
    raise SystemExit(
        "Run this from the PTMC-Rostering repository root."
    )

text = PAGE.read_text()

marker = '        st.divider()\n        st.subheader(\n            "Delete requirement"\n        )\n\n        requirement_by_id = {\n            str(item["id"]): item\n            for item in requirements\n        }\n'
editor = '        st.divider()\n        st.subheader(\n            "Edit requirement"\n        )\n\n        requirement_by_id = {\n            str(item["id"]): item\n            for item in requirements\n        }\n\n        edit_requirement_id = st.selectbox(\n            "Select requirement to edit",\n            options=list(requirement_by_id),\n            format_func=lambda item_id: (\n                f"{requirement_by_id[item_id][\'requesting_unit\']} — "\n                f"{requirement_by_id[item_id][\'cover_type\']} — "\n                f"{requirement_by_id[item_id][\'start_date\']:%d %b} to "\n                f"{requirement_by_id[item_id][\'end_date\']:%d %b}"\n            ),\n            key="edit_cover_requirement_selector",\n        )\n\n        edit_requirement = requirement_by_id[\n            edit_requirement_id\n        ]\n\n        linked_manual_rows = []\n\n        try:\n            linked_response = (\n                get_supabase()\n                .table(\n                    "roster_manual_assignments"\n                )\n                .select(\n                    "id,personnel_name,assignment_date,assignment_kind"\n                )\n                .eq(\n                    "cover_requirement_id",\n                    edit_requirement_id,\n                )\n                .execute()\n            )\n\n            linked_manual_rows = (\n                linked_response.data\n                or []\n            )\n        except Exception as exc:\n            st.warning(\n                "Unable to check linked manual assignments. "\n                f"{exc}"\n            )\n\n        type_by_id = {\n            str(row["id"]): row\n            for row in active_cover_types\n        }\n\n        current_type_id = str(\n            edit_requirement.get(\n                "cover_type_id"\n            )\n            or ""\n        )\n\n        if (\n            current_type_id\n            not in type_by_id\n        ):\n            matching_type = next(\n                (\n                    row\n                    for row\n                    in active_cover_types\n                    if str(\n                        row["cover_type"]\n                    ).upper()\n                    == str(\n                        edit_requirement[\n                            "cover_type"\n                        ]\n                    ).upper()\n                ),\n                None,\n            )\n\n            if matching_type:\n                current_type_id = str(\n                    matching_type["id"]\n                )\n\n        type_options = list(\n            type_by_id\n        )\n\n        type_index = (\n            type_options.index(\n                current_type_id\n            )\n            if current_type_id\n            in type_options\n            else 0\n        )\n\n        e1, e2 = st.columns(2)\n\n        with e1:\n            edit_unit = st.text_input(\n                "Requesting unit",\n                value=str(\n                    edit_requirement[\n                        "requesting_unit"\n                    ]\n                ),\n                key=(\n                    "edit_requirement_unit_"\n                    + edit_requirement_id\n                ),\n            )\n\n        with e2:\n            edit_type_id = st.selectbox(\n                "Cover type",\n                options=type_options,\n                index=type_index,\n                format_func=lambda item_id: str(\n                    type_by_id[\n                        item_id\n                    ][\n                        "cover_type"\n                    ]\n                ),\n                key=(\n                    "edit_requirement_type_"\n                    + edit_requirement_id\n                ),\n            )\n\n        selected_edit_type = (\n            type_by_id[\n                edit_type_id\n            ]\n        )\n\n        edit_cover_type = str(\n            selected_edit_type[\n                "cover_type"\n            ]\n        ).upper()\n\n        edit_points = float(\n            selected_edit_type.get(\n                "points"\n            )\n            or 0.0\n        )\n\n        d1, d2, d3, d4 = st.columns(\n            4\n        )\n\n        with d1:\n            edit_start = st.date_input(\n                "Start date",\n                value=edit_requirement[\n                    "start_date"\n                ],\n                min_value=selected_month,\n                max_value=selected_month_end,\n                format="DD/MM/YYYY",\n                key=(\n                    "edit_requirement_start_"\n                    + edit_requirement_id\n                ),\n            )\n\n        with d2:\n            safe_end_value = max(\n                edit_start,\n                edit_requirement[\n                    "end_date"\n                ],\n            )\n\n            edit_end = st.date_input(\n                "End date",\n                value=safe_end_value,\n                min_value=edit_start,\n                max_value=selected_month_end,\n                format="DD/MM/YYYY",\n                key=(\n                    "edit_requirement_end_"\n                    + edit_requirement_id\n                    + "_"\n                    + edit_start.isoformat()\n                ),\n            )\n\n        current_session = str(\n            edit_requirement.get(\n                "session"\n            )\n            or "FULL_DAY"\n        ).upper()\n\n        session_index = (\n            SESSION_OPTIONS.index(\n                current_session\n            )\n            if current_session\n            in SESSION_OPTIONS\n            else 2\n        )\n\n        with d3:\n            edit_session = st.selectbox(\n                "Session",\n                options=SESSION_OPTIONS,\n                index=session_index,\n                format_func=lambda value: (\n                    SESSION_LABELS[\n                        value\n                    ]\n                ),\n                key=(\n                    "edit_requirement_session_"\n                    + edit_requirement_id\n                ),\n            )\n\n        with d4:\n            edit_quantity = st.number_input(\n                "Personnel required",\n                min_value=1,\n                max_value=20,\n                value=int(\n                    edit_requirement[\n                        "personnel_required"\n                    ]\n                ),\n                step=1,\n                key=(\n                    "edit_requirement_qty_"\n                    + edit_requirement_id\n                ),\n            )\n\n        edit_mandatory = st.checkbox(\n            "Mandatory requirement",\n            value=bool(\n                edit_requirement[\n                    "mandatory"\n                ]\n            ),\n            key=(\n                "edit_requirement_mandatory_"\n                + edit_requirement_id\n            ),\n        )\n\n        edit_remarks = st.text_area(\n            "Remarks",\n            value=str(\n                edit_requirement.get(\n                    "remarks"\n                )\n                or ""\n            ),\n            key=(\n                "edit_requirement_remarks_"\n                + edit_requirement_id\n            ),\n        )\n\n        structural_change = any(\n            [\n                edit_cover_type\n                != str(\n                    edit_requirement[\n                        "cover_type"\n                    ]\n                ).upper(),\n                edit_start\n                != edit_requirement[\n                    "start_date"\n                ],\n                edit_end\n                != edit_requirement[\n                    "end_date"\n                ],\n                edit_session\n                != current_session,\n                int(\n                    edit_quantity\n                )\n                != int(\n                    edit_requirement[\n                        "personnel_required"\n                    ]\n                ),\n            ]\n        )\n\n        confirm_linked_change = False\n\n        if (\n            linked_manual_rows\n            and structural_change\n        ):\n            st.warning(\n                f"This requirement has {len(linked_manual_rows)} "\n                "linked manual assignment row(s). Changing its cover type, "\n                "dates, session, or personnel requirement may make those "\n                "manual assignments inconsistent."\n            )\n\n            confirm_linked_change = (\n                st.checkbox(\n                    "I understand and want to save the structural change",\n                    key=(\n                        "confirm_linked_requirement_change_"\n                        + edit_requirement_id\n                    ),\n                )\n            )\n\n        if st.button(\n            "Save requirement changes",\n            type="primary",\n            use_container_width=True,\n            key=(\n                "save_cover_requirement_"\n                + edit_requirement_id\n            ),\n            disabled=(\n                bool(\n                    linked_manual_rows\n                )\n                and structural_change\n                and not confirm_linked_change\n            ),\n        ):\n            if not edit_unit.strip():\n                st.error(\n                    "Requesting unit is required."\n                )\n            else:\n                payload = {\n                    "requesting_unit": (\n                        edit_unit\n                        .strip()\n                        .upper()\n                    ),\n                    "cover_category": (\n                        legacy_category_for_type(\n                            edit_cover_type\n                        )\n                    ),\n                    "cover_type": (\n                        edit_cover_type\n                    ),\n                    "cover_type_id": (\n                        edit_type_id\n                    ),\n                    "points_snapshot": (\n                        edit_points\n                    ),\n                    "session": (\n                        edit_session\n                    ),\n                    "start_date": (\n                        edit_start\n                        .isoformat()\n                    ),\n                    "end_date": (\n                        edit_end\n                        .isoformat()\n                    ),\n                    "personnel_required": (\n                        int(\n                            edit_quantity\n                        )\n                    ),\n                    "mandatory": (\n                        bool(\n                            edit_mandatory\n                        )\n                    ),\n                    "remarks": (\n                        edit_remarks\n                        .strip()\n                        or None\n                    ),\n                }\n\n                try:\n                    (\n                        get_supabase()\n                        .table(\n                            "roster_cover_requirements"\n                        )\n                        .update(\n                            payload\n                        )\n                        .eq(\n                            "id",\n                            edit_requirement_id,\n                        )\n                        .execute()\n                    )\n                except Exception as exc:\n                    st.error(\n                        "Unable to update requirement. "\n                        f"{exc}"\n                    )\n                else:\n                    clear_cover_requirement_cache()\n                    st.success(\n                        "Cover requirement updated."\n                    )\n                    st.rerun()\n\n        st.divider()\n        st.subheader(\n            "Delete requirement"\n        )\n'

if marker not in text:
    raise SystemExit(
        "Could not find the current Delete requirement section. "
        "No file was changed."
    )

text = text.replace(
    marker,
    editor,
    1,
)

compile(
    text,
    str(PAGE),
    "exec",
)

backup = PAGE.with_suffix(
    ".py.step24_backup"
)

if not backup.exists():
    backup.write_text(
        PAGE.read_text()
    )

PAGE.write_text(
    text
)

print("Step 24 applied successfully.")
print("Cover requirement editor added beneath the Planner table.")
